CREATE TABLE t_new (id Uint64 NOT NULL, a Utf8, b Utf8, PRIMARY KEY (id, a));
INSERT INTO t_new (id, a, b) SELECT id, a, b FROM t;
ALTER TABLE t RENAME TO t_old;
