DROP TABLE t_old;
CREATE TABLE t_lossy (id Uint64 NOT NULL, a Utf8, PRIMARY KEY (id));
INSERT INTO t_lossy (id, a) SELECT id, a FROM t;
ALTER TABLE t RENAME TO t_gone;
ALTER TABLE t_lossy RENAME TO t;
DROP TABLE t_gone;
CREATE TABLE r2 (id Uint64 NOT NULL, PRIMARY KEY (id));
INSERT INTO r2 SELECT * FROM r;
DROP TABLE r;
ALTER TABLE r2 RENAME TO r;
CREATE TABLE r3 (id Uint64 NOT NULL, PRIMARY KEY (id));
INSERT INTO r3 SELECT DISTINCT * FROM r;
DROP TABLE r;
ALTER TABLE r3 RENAME TO r;
CREATE TABLE r4 (id Uint64 NOT NULL, PRIMARY KEY (id));
INSERT INTO r4 SELECT * FROM r WHERE id > 1;
DROP TABLE r;
ALTER TABLE r4 RENAME TO r;
CREATE TABLE r5 (id Uint64 NOT NULL, PRIMARY KEY (id));
INSERT INTO r5 SELECT * FROM r;
DROP TABLE r, r5;
